\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Venue Color Theme (WHO Blue & Amber) ──
\definecolor{primary}{HTML}{005B9F}     % deep blue
\definecolor{secondary}{HTML}{0072CE}   % medium blue
\definecolor{accent}{HTML}{E37222}      % warm amber
\definecolor{bgposter}{HTML}{F4F7F9}    % light cool gray background
\definecolor{redbg}{HTML}{FFF8F4}       % amber tint
\definecolor{bluebg}{HTML}{F0F6FA}      % blue tint
\definecolor{darkbg}{HTML}{F2F7F9}      % deep tint
\definecolor{redtitlebg}{HTML}{FFEFE6}  % amber title bg
\definecolor{bluetitlebg}{HTML}{E1F0F9} % blue title bg
\definecolor{darktitlebg}{HTML}{E6F0F5} % deep title bg
\definecolor{textdark}{HTML}{1A202C}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{stathighlight}{HTML}{EAF4F9} % stat callout highlight

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=36pt, itemsep=12pt, parsep=6pt, topsep=6pt,
  label={\color{secondary}\Large$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=36pt, itemsep=12pt, parsep=6pt, topsep=6pt,
  label={\color{primary}\Large\bfseries\arabic*.}}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=redbg,
    borderline west={8pt}{0pt}{accent},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=12pt, bottomtitle=12pt, lefttitle=24pt, righttitle=24pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.15},
  },
  bluecard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=bluebg,
    borderline west={8pt}{0pt}{secondary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=12pt, bottomtitle=12pt, lefttitle=24pt, righttitle=24pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=darkbg,
    borderline west={8pt}{0pt}{primary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=12pt, bottomtitle=12pt, lefttitle=24pt, righttitle=24pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=primary!15!white,
    borderline west={8pt}{0pt}{primary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{46}{56}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=12pt, bottomtitle=12pt, lefttitle=24pt, righttitle=24pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\newcommand{\phasebadge}[1]{%
  \begin{tikzpicture}[baseline=-0.3em]
    \node[shape=circle,fill=currentcolor,text=white,inner sep=6pt,font=\fontsize{40}{48}\selectfont\bfseries] {#1};
  \end{tikzpicture}\hspace{10pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=4mm, xshift=8mm, yshift=8mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=12pt, boxrule=0pt,
  left=30pt, right=30pt, top=24pt, bottom=24pt,
  halign=center, valign=center,
  drop shadow={opacity=0.25}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries COVID-19 Emergency Response: From Detection to Recovery}\\[16pt]
  {\fontsize{36}{44}\selectfont\color{white!90} A step-by-step overview of the structured, WHO-guided multi-phase process.}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{white!70} Global Architecture for Health Emergencies \hfill Data as of Mid-2023}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=0pt, right=0pt, top=0pt, bottom=0pt,
  valign=center,
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!40}{white}{\parbox{0.9\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{primary} 194}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\bfseries Member States Coordinated}\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!40}{white}{\parbox{0.9\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{primary} 6}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\bfseries WHO Regions Covered}\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.26\linewidth}\centering
    \fcolorbox{primary!40}{white}{\parbox{0.9\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{primary} \char`\~1.9B}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\bfseries COVAX Doses Delivered}\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{primary!40}{white}{\parbox{0.9\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{64}{76}\selectfont\bfseries\color{primary} 200+}\\[8pt]
      {\fontsize{24}{30}\selectfont\color{textdark}\bfseries Guidance Documents}\vspace{16pt}%
    }}
  \end{minipage}
}

% ══ CONTENT CARDS ══

% PHASE 1 (Col 1, Row 5-10)
\posterbox[darkcard, title={\phasebadge{1} Surveillance \& Early Detection}
]{name=phase1, column=1, between=row5 and row10}{
  \fontsize{30}{42}\selectfont
  \begin{itemize}
    \item \textbf{Robust Global Tracking:} National and sub-national labs report unusual respiratory clusters directly to WHO.
    \item \textbf{Rapid Information Sharing:} Activated via the International Health Regulations (IHR) framework.
    \item \textbf{Early Alerts:} First Disease Outbreak News bulletin published Jan 5, 2020.
  \end{itemize}
  \vspace{10pt}
  \begin{center}
    \colorbox{primary!15}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}
      \textbf{$\Rightarrow$ Identify and confirm disease signals immediately.}
      \vspace{6pt}
    }}
  \end{center}
}

% PHASE 2 (Col 2, Row 5-10)
\posterbox[darkcard, title={\phasebadge{2} Risk Assessment \& Alert}
]{name=phase2, column=2, between=row5 and row10}{
  \fontsize{30}{42}\selectfont
  \begin{itemize}
    \item \textbf{Rapid Evaluation:} Assess spread likelihood, illness severity, and health system capacity.
    \item \textbf{Regular Updates:} Continuous situation reports and Independent Oversight review.
    \item \textbf{Global Declaration:} COVID-19 declared a Public Health Emergency of International Concern (PHEIC) on Jan 30, 2020.
  \end{itemize}
  \vspace{10pt}
  \begin{center}
    \colorbox{primary!15}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}
      \textbf{$\Rightarrow$ Communicate alert levels to all member states.}
      \vspace{6pt}
    }}
  \end{center}
}

% PHASE 3 (Col 1, Row 10-15)
\posterbox[bluecard, title={\phasebadge{3} Response \& Clinical Care}
]{name=phase3, column=1, between=row10 and row15}{
  \fontsize{30}{42}\selectfont
  Mobilization of technical teams across critical pillars:
  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Infection Control:} PPE guidance, hand hygiene, and facility decontamination protocols.
    \item \textbf{Clinical Management:} Standardized treatment protocols, ICU guidelines, and oxygen therapy.
    \item \textbf{Supply \& Logistics:} Procurement of essential medicines, diagnostics, and equipment.
  \end{itemize}
  \vspace{10pt}
  \begin{center}
    \colorbox{secondary!15}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}
      \textbf{$\Rightarrow$ Coordinated via WHO Health Emergencies Programme.}
      \vspace{6pt}
    }}
  \end{center}
}

% PHASE 4 (Col 2, Row 10-16.5) - Slightly larger
\posterbox[redcard, title={\phasebadge{4} Public Health Measures}
]{name=phase4, column=2, between=row10 and row16}{
  \fontsize{30}{42}\selectfont
  Community-level interventions are the frontline of defense:
  \vspace{8pt}
  \begin{itemize}
    \item \textbf{Testing \& Tracing:} Scaled PCR and rapid antigen testing, supported by robust contact tracing.
    \item \textbf{Isolation:} Evidence-based quarantine duration guidelines updated for new variants.
    \item \textbf{Vaccination:} Massive COVAX rollout prioritizing health workers and vulnerable groups.
    \item \textbf{Communication:} Combating misinformation across multilingual global channels.
  \end{itemize}
  \vspace{10pt}
  \begin{center}
    \colorbox{accent!15}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}
      \textbf{$\Rightarrow$ Slow transmission and save lives at the community level.}
      \vspace{6pt}
    }}
  \end{center}
}

% PHASE 5 (Col 1, Row 15-20)
\posterbox[darkcard, title={\phasebadge{5} Recovery \& Resilience}
]{name=phase5, column=1, between=row15 and bottom}{
  \fontsize{30}{42}\selectfont
  \begin{itemize}
    \item \textbf{Restoring Services:} Rebuilding routine health care disrupted by the pandemic.
    \item \textbf{Long-term Care:} Addressing long COVID and lasting mental health impacts.
    \item \textbf{Future Preparedness:} Updating national action plans for the next major outbreak.
  \end{itemize}
  \vspace{10pt}
  \begin{center}
    \colorbox{primary!15}{\parbox{0.94\linewidth}{%
      \centering\vspace{6pt}
      \textbf{$\Rightarrow$ Transition to a sustained, resilient global health recovery.}
      \vspace{6pt}
    }}
  \end{center}
}

% KEY TAKEAWAYS (Col 2, Row 16-20)
\posterbox[highlightcard, title={Global Impact \& Vision}
]{name=takeaways, column=2, between=row16 and bottom}{
  \fontsize{30}{42}\selectfont
  \begin{itemize}
    \item \textbf{Unprecedented Coordination:}\\194 nations aligned under a single structured response framework.
    \item \textbf{Data-Driven Action:}\\Millions of daily data points provided real-time situational awareness.
    \item \textbf{Blueprint for the Future:}\\The structured 5-phase process builds enduring global health architecture against future pandemics.
  \end{itemize}
}

\end{tcbposter}
\end{document}

